1	// Oracle differential compare. See state_diff.hpp for the policy.
2	#include "state_diff.hpp"
3	
4	#include <cstdio>
5	#include <string>
6	#include <string_view>
7	
8	namespace andes_sim {
9	
10	namespace {
11	
12	void cmp(DiffReport& r, const std::string& field, unsigned long long ref,
13	         unsigned long long got) {
14	  ++r.compared;
15	  if (ref != got) r.diffs.push_back({field, ref, got});
16	}
17	
18	}  // namespace
19	
20	DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
21	                       const std::vector<std::string>& andes_supported) {
22	  DiffReport r;
23	
24	  cmp(r, "magic", ref.magic, got.magic);
25	  cmp(r, "version", ref.version, got.version);
26	  cmp(r, "flags", ref.flags, got.flags);
27	  cmp(r, "hart_id", ref.hart_id, got.hart_id);
28	  cmp(r, "priv", ref.priv, got.priv);
29	  cmp(r, "pc", ref.pc, got.pc);
30	
31	  // mepc/mcause: in the trap-free hybrid ROI they round-trip (L24: restored at
32	  // resume, re-read at drain). mtval/mstatus stay out of scope where they are
33	  // implementation-defined / carry dirty bits (false positives).
34	  cmp(r, "mepc", ref.mepc, got.mepc);
35	  cmp(r, "mcause", ref.mcause, got.mcause);
36	
37	  // Round-trip M-mode CSRs: mscratch (L23) and mtval/mie (L24) are restored at
38	  // resume and re-read at drain, so a trap-free ROI must match the oracle on
39	  // them. mip is excluded: its pending bits are hardware/platform-driven
40	  // (timer/external) and diverge between QEMU's functional clock and vsim's
41	  // cycle clock even with no trap (it still round-trips into the drained
42	  // record, just not the verifier).
43	  cmp(r, "mscratch", ref.mscratch, got.mscratch);
44	  cmp(r, "mtval", ref.mtval, got.mtval);
45	  cmp(r, "mie", ref.mie, got.mie);
46	
47	  for (int i = 0; i < 32; ++i)
48	    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);
49	
50	  if (ref.flags & HYBRID_FLAG_FP) {
51	    for (int i = 0; i < 32; ++i)
52	      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
53	    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
54	  }
55	
56	  if (ref.flags & HYBRID_FLAG_V) {
57	    cmp(r, "vstart", ref.vstart, got.vstart);
58	    cmp(r, "vtype", ref.vtype, got.vtype);
59	    cmp(r, "vl", ref.vl, got.vl);
60	    cmp(r, "vlenb", ref.vlenb, got.vlenb);
61	    cmp(r, "vxsat", ref.vxsat, got.vxsat);
62	    cmp(r, "vxrm", ref.vxrm, got.vxrm);
63	    cmp(r, "vcsr", ref.vcsr, got.vcsr);
64	
65	    // One compared "field" per vector register; report the first differing
66	    // byte as "v<i>[<byte>]".
67	    for (int i = 0; i < 32; ++i) {
68	      ++r.compared;
69	      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
70	      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
71	      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
72	        if (a[j] != b[j]) {
73	          r.diffs.push_back({"v" + std::to_string(i) + "[" +
74	                                 std::to_string(j) + "]",
75	                             a[j], b[j]});
76	          break;
77	        }
78	      }
79	    }
80	  }
81	
82	  // Andes V5 CSR block (v3): the boot-static memory-system/extension CSRs plus
83	  // the DSP overflow flag round-trip through the trap-free ROI (ResumeDriver
84	  // restores them, StateDrain re-reads them), so a correct transport matches the
85	  // oracle. The X-macro is the single source of truth shared with the plugin
86	  // drain / resume / drain re-read, so this list can never drift out of sync.
87	  //
88	  // Exclusion: msp_bound/msp_base are the HW stack-protection bound registers.
89	  // QEMU resets them to all-ones; a vsim core that does not implement HW stack
90	  // protection drains 0. That divergence is an engine-implementation artifact,
91	  // not a transport bug (the restore is a tolerant no-op on a core lacking the
92	  // CSR) -- so they are transported but excluded from strict verify, exactly
93	  // like mip's hardware-driven pending bits.
94	  auto andes_verify_excluded = [](std::string_view name) {
95	    // msp_bound/msp_base: engine-reset-divergent HW stack-protection bounds.
96	    // milmb/mdlmb: ILM/DLM base+enable CSRs. The base address round-trips, but
97	    // the enable bit (bit 0) is HW-presence state -- the vsim RTL has the local
98	    // memories and drains EN=1, while QEMU models none and drains EN=0. Same
99	    // class as msp_bound/msp_base (an engine-implementation artifact, not a
100	    // transport bug), so excluded rather than half-compared via a bit mask.
101	    // mhpmcounter3..6: hardware performance counters that increment DURING the
102	    // ROI, so the vsim (cycle) and QEMU (functional) values legitimately differ
103	    // -- transported and restored, but not strict-compared, like mcycle/mip.
104	    // mdcause: vsim models it as HW-set (a direct write drains back 0).
105	    // tdata1/tcontrol/mcontext: debug-trigger state whose reset defaults and
106	    // WARL widths differ between QEMU and vsim. All transported + restored, but
107	    // not cross-engine strict-compared.
108	    static constexpr std::string_view kExcluded[] = {
109	        "msp_bound", "msp_base", "milmb", "mdlmb",
110	        "mhpmcounter3", "mhpmcounter4", "mhpmcounter5", "mhpmcounter6",
111	        "mdcause", "tdata1", "tcontrol", "mcontext"};
112	    for (std::string_view e : kExcluded)
113	      if (e == name) return true;
114	    return false;
115	  };
116	  // Engine capability gate (S4): skip any Andes CSR the cycle engine does not
117	  // implement. Empty list = no engine info -> compare all (back-compat).
118	  auto andes_supported_csr = [&](std::string_view name) {
119	    if (andes_supported.empty()) return true;
120	    for (const std::string& s : andes_supported)
121	      if (s == name) return true;
122	    return false;
123	  };
124	  if (ref.flags & HYBRID_FLAG_ANDES) {
125	#define X(field, addr, name)                                  \
126	  if (!andes_verify_excluded(name) && andes_supported_csr(name)) \
127	    cmp(r, name, ref.andes.field, got.andes.field);
128	    HYBRID_ANDES_CSR_LIST(X)
129	#undef X
130	    if (andes_supported_csr("pmacfg"))
131	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
132	        cmp(r, "pmacfg" + std::to_string(i), ref.andes.pmacfg[i],
133	            got.andes.pmacfg[i]);
134	    if (andes_supported_csr("pmaaddr"))
135	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
136	        cmp(r, "pmaaddr" + std::to_string(i), ref.andes.pmaaddr[i],
137	            got.andes.pmaaddr[i]);
138	  }
139	
140	  // M-ext CSR block (v4): same gate (the engine's supported list now includes
141	  // the M-ext names) and the same HW-driven exclusion. A CSR the engine lacks
142	  // is neither restored, drained, nor compared.
143	  if (ref.flags & HYBRID_FLAG_M_EXT) {
144	#define X(field, addr, name)                                    \
145	  if (!andes_verify_excluded(name) && andes_supported_csr(name)) \
146	    cmp(r, name, ref.m_ext.field, got.m_ext.field);
147	    HYBRID_M_EXT_CSR_LIST(X)
148	#undef X
149	  }
150	
151	  return r;
152	}
153	
154	void print_diff_report(const DiffReport& r) {
155	  for (const FieldDiff& d : r.diffs)
156	    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
157	                d.ref, d.got);
158	  if (r.ok()) {
159	    std::printf(
160	        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
161	        "excluded)\n",
162	        r.compared);
163	  } else {
164	    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
165	                r.diffs.size(), r.compared);
166	  }
167	}
168	
169	}  // namespace andes_sim
